mapper.select:
select 
from preg_diet_record d
where d.del_flag = '0'

    and d.meal_type = #{mealType}


    and d.record_date >= #{from}


    and d.record_date <= #{to}

order by d.occurred_at desc, d.id desc

select d.record_date as recordDate, count(1) as total
from preg_diet_record d
where d.record_date >= #{from}
  and d.record_date <= #{to}
  and d.del_flag = '0'
group by d.record_date
